class RegressionMPR(object):

    # Function for checking overfitting
    def _overfit_warning(self, num_var, num_datap):
        self.premature_exit = False
        if num_var > 0.5 * num_datap and num_var < num_datap:
            self.fit_warning = "overfit"
            msg = """
                The number of variables in feature space is larger than half of the number of
                datapoints. Overfitting may occur. Reducing the polynomial power may address
                the potential overfitting problem.
                """

            logger.warning(msg)
        elif num_var > num_datap:
            self.fit_warning = "nomodel"
            msg = """
                The number of variables in feature space is larger than the number of
                datapoints. Please provide more datapoints or select lower degrees of polynomials.
                """
            self.premature_exit = True
            self.premature_exit_msg = msg
            logger.warning(msg)
            return
        else:
            self.fit_warning = None

