    # Prediction by casting future points in feature space

    def feature_importance(self):
        # logger.debug("Calculating feature importance")
        n_features = self.feature_columns.shape[1]
        if len(self.test_ind) < 5:
            X_fi, y_fi = self.feature_columns, self.target_columns
        else:
            X_fi, y_fi = (
                self.feature_columns.iloc[self.test_ind],
                self.target_columns.iloc[self.test_ind],
            )

        y_pred = self.predict(X_fi)
        baseline_performance = mean_squared_error(y_fi, y_pred)
        logger.info(f"Baseline metric: {baseline_performance}")

        if len(y_fi) < 5:
            raise ValueError(
                "Data must be longer than 5 samples to compute Permutation Feature Importance"
            )
        elif len(y_fi) < 20:
            n_run = 10
        elif len(y_fi) < 50:
            n_run = 3
        else:
            n_run = 1

        importances = np.zeros([n_features, n_run])
        importances_avg = np.zeros([n_features, n_run])

        for j in range(n_run):
            for i, label in enumerate(X_fi):
                permuted_X = X_fi.copy(deep=True)
                permuted_X[label] = permuted_X[label].values[
                    np.random.permutation(len(y_fi))
                ]
                y_pred = self.predict(permuted_X)
                permuted_performance = mean_squared_error(y_fi, y_pred)
                importances[i, j] = baseline_performance - permuted_performance
            importances[:, j] /= importances[:, j].sum(axis=0)
            importances_avg[:, j] = importances[:, : j + 1].mean(axis=1)

        return importances

    def predict(self, X_t):

        if hasattr(self, "categorical_transformer") and isinstance(X_t, pd.DataFrame):
            X_t = self.categorical_transformer.transform(X_t)

        # Cast into a reduced order space if any
        if self.dr_basis is not None:
            X_t = self.dr_basis.transform(X_t)

        # Scale the data with same scaling
        if self.input_scaling is not None:

            X_t = self.scaling_func.transform(X_t)

        # Casting the test input into feature space
        if hasattr(self, "polynomial_transformer"):
            Xf_t = self.polynomial_transformer.transform(X_t)
        else:
            Xf_t = X_t.copy()
            X_t = None

        # Dask or regular version
        if self.use_dask:
            return self.MPR.predict(Xf_t).compute()
        else:
            return self.MPR.predict(Xf_t)

